package com.kingzcheung.xime.settings
import java.io.File
import java.util.zip.ZipEntry
import java.util.zip.ZipOutputStream

class Context(val filesDir: File)
object Log { fun i(tag: String, text: String) {} }
object FileLogger { fun w(tag: String, text: String) {} }
object SchemaManager { fun getMarketDir(context: Context) = File(context.filesDir, "market") }
object BackupManager {
 const val META_PREFIX = "_xime_backup/"
 const val CELLS_DIR = "cells"
 val SETTINGS_PREFS = emptySet<String>()
 val PARTIAL_PREFS = emptyMap<String, Set<String>>()
 fun isFilesEntry(path: String, personal: Boolean) = false
 fun isCellEntry(path: String) = false
}
object OriginalMigration {
 const val TAG = "MigrationHost"
 fun migrateOldStructure(context: Context, rimeDir: File) {
        val oldSharedDir = File(context.filesDir, "rime/shared")
        val oldUserDir = File(context.filesDir, "rime/user")

        if (!oldSharedDir.exists() && !oldUserDir.exists()) return

        Log.i(TAG, "Migrating old rime directory structure to single rime/ dir...")

        if (!rimeDir.exists()) rimeDir.mkdirs()

        // 迁移 user 数据（用户配置、build 产物、userdb）
        if (oldUserDir.exists()) {
            oldUserDir.listFiles()?.forEach { file ->
                val target = File(rimeDir, file.name)
                if (!target.exists()) {
                    file.renameTo(target)
                }
            }
        }

        // 迁移 shared 数据（方案文件）
        if (oldSharedDir.exists()) {
            oldSharedDir.listFiles()?.forEach { file ->
                val target = File(rimeDir, file.name)
                if (!target.exists()) {
                    file.renameTo(target)
                }
            }
        }

        // 删除旧目录
        oldSharedDir.deleteRecursively()
        oldUserDir.deleteRecursively()

        Log.i(TAG, "Migration complete")
    }

fun migrateOldMarketDir(context: Context) {
        val oldMarket = File(context.filesDir, "rime/market")
        if (!oldMarket.exists()) return

        val newMarket = SchemaManager.getMarketDir(context)
        if (!newMarket.exists()) {
            // 新位置不存在，直接重命名
            if (oldMarket.renameTo(newMarket)) {
                Log.i(TAG, "Migrated rime/market/ -> market/")
            } else {
                FileLogger.w(TAG, "Failed to rename rime/market/ to market/")
            }
        } else {
            // 新位置已存在，逐项合并
            oldMarket.listFiles()?.forEach { sub ->
                val target = File(newMarket, sub.name)
                if (!target.exists()) {
                    sub.renameTo(target)
                }
            }
            oldMarket.deleteRecursively()
            Log.i(TAG, "Merged rime/market/ into market/")
        }
    }
}
fun write(root: File, name: String, content: String) = File(root,name).apply { parentFile.mkdirs(); writeText(content) }
fun backup(vararg entries: Pair<String,String>): ByteArray {
 val buffer=java.io.ByteArrayOutputStream()
 ZipOutputStream(buffer).use { zip ->
  for((name,text) in entries) { zip.putNextEntry(ZipEntry(name)); zip.write(text.toByteArray()); zip.closeEntry() }
 }
 return buffer.toByteArray()
}
fun restore(root:File, archive:ByteArray) = BackupRestoreTransaction.restore(root, object:BackupPreferenceStore {
 override fun validate(json:ByteArray) { check(json.toString(Charsets.UTF_8)=="{}") }
 override fun snapshot(name:String) = "{}".toByteArray()
 override fun restore(name:String,json:ByteArray,replace:Boolean) {}
},archive)
fun main() {
 val base=kotlin.io.path.createTempDirectory("lantype-migration-probe-").toFile()
 try {
  val conflict=File(base,"conflict").apply{mkdirs()}
  write(conflict,"rime/rime_ice.userdb/CURRENT","current-flat-database")
  write(conflict,"rime/default.custom.yaml","current-flat-settings")
  check(restore(conflict,backup("_xime_backup/settings.json" to "{}",
      "user/rime_ice.userdb/CURRENT" to "restored-legacy-database",
      "user/rime_ice.userdb/000001.ldb" to "legacy-personal-word-data",
      "user/default.custom.yaml" to "restored-legacy-settings")).isSuccess)
  check(File(conflict,"rime/user/rime_ice.userdb/000001.ldb").readText()=="legacy-personal-word-data")
  OriginalMigration.migrateOldStructure(Context(conflict),File(conflict,"rime"))
  check(File(conflict,"rime/rime_ice.userdb/CURRENT").readText()=="current-flat-database")
  check(File(conflict,"rime/default.custom.yaml").readText()=="current-flat-settings")
  check(!File(conflict,"rime/user").exists())
  check(!File(conflict,"rime/rime_ice.userdb/000001.ldb").exists())

  val fresh=File(base,"fresh").apply{mkdirs()}
  check(restore(fresh,backup("_xime_backup/settings.json" to "{}",
      "user/rime_ice.userdb/CURRENT" to "legacy-database",
      "user/rime_ice.userdb/000001.ldb" to "legacy-personal-word-data")).isSuccess)
  OriginalMigration.migrateOldStructure(Context(fresh),File(fresh,"rime"))
  check(File(fresh,"rime/rime_ice.userdb/000001.ldb").readText()=="legacy-personal-word-data")
  check(!File(fresh,"rime/user").exists())

  val market=File(base,"market-conflict").apply{mkdirs()}
  write(market,"market/custom/active.schema.yaml","current")
  write(market,"rime/market/custom/personal.dict.yaml","legacy-market-personal-words")
  OriginalMigration.migrateOldMarketDir(Context(market))
  check(File(market,"market/custom/active.schema.yaml").readText()=="current")
  check(!File(market,"market/custom/personal.dict.yaml").exists())
  check(!File(market,"rime/market").exists())
  println("{\"cases\":3,\"legacyRestoreConflictDataLost\":true,\"noConflictMigratedPreserved\":true,\"marketConflictDataLost\":true,\"androidOrNativeRun\":false}")
 } finally { base.deleteRecursively() }
}
